def svg(name, color="#ffffff", night=False):
    """아이콘 하나를 SVG 문자열로 만듭니다. 없으면 흐림으로 대신합니다."""
    if night:
        shape = SHAPES.get(name + "_night")
        if shape is None:
            shape = SHAPES.get(name)
    else:
        shape = SHAPES.get(name)
    if shape is None:
        shape = SHAPES["cloudy"]
    box, paths = shape
    body = "".join(
        '<path d="%s" fill="%s"/>' % (d, color) for d in paths)
    return (
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="%s">%s</svg>'
        % (box, body))
